  "connectors": { pl: "konektory", en: "connectors", enAlt: ["connector"], def: "Karty własne o sąsiednich albo prawie sąsiednich wartościach, np. 8-7 lub 9-8; łatwiej z nich ułożyć strita.", area: "preflop", forms: ["konektory","konektor","konektora","konektorem","konektorów","konektorami","konektorom","konektorach"] },
