  "4-bet": { pl: "4-bet", en: "4-bet", enAlt: ["four-bet"], def: "Przebicie 3-betu, czyli czwarty zakład w rundzie licytacji.", area: "preflop" },
  "limp": { pl: "limp", en: "limp", enAlt: [], def: "Wejście do puli przed flopem przez samo sprawdzenie dużego blinda, gdy nikt jeszcze nie przebił.", area: "preflop" },
